    E("Origin: (%.2f, %.2f, %.2f)","Origen: (%.2f, %.2f, %.2f)","Origem: (%.2f, %.2f, %.2f)","Origine : (%.2f, %.2f, %.2f)","Ursprung: (%.2f, %.2f, %.2f)","Origine: (%.2f, %.2f, %.2f)"),
