    E("Save File", "Guardar archivo", "Salvar arquivo", "Enregistrer le fichier", "Datei speichern", "Salva file"),
    E("Open File", "Abrir archivo", "Abrir arquivo", "Ouvrir un fichier", "Datei öffnen", "Apri file"),
